using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
[InitializeOnLoad]public static class Glass2VisibleFix{static double next;static Glass2VisibleFix(){EditorApplication.update+=Tick;}static void Tick(){if(EditorApplication.timeSinceStartup<next)return;next=EditorApplication.timeSinceStartup+4;if(File.Exists("D:/-11-scene3-audit/glass2-visible.txt")||EditorApplication.isUpdating||EditorApplication.isCompiling||EditorApplication.isPlayingOrWillChangePlaymode)return;var s=UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(s.name!="scene3")return;try{var rs=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Renderer>(true)).Where(r=>r.name.Equals("glass2",StringComparison.OrdinalIgnoreCase)).ToArray();if(rs.Length!=1)throw new Exception("Expected one glass2 renderer, found "+rs.Length);var r=rs[0];var shader=Shader.Find("BlenderScene3/Glass2VisibleFrost");if(!shader||ShaderUtil.ShaderHasError(shader))throw new Exception("Glass2 shader not ready");EditorSceneManager.SaveScene(s);File.Copy(s.path,"D:/-11-scene3-audit/scene3.before-visible-glass2.unity",true);
 var cubePath="Assets/BlenderScene3/Materials/Glass2Environment.asset";var cube=AssetDatabase.LoadAssetAtPath<Cubemap>(cubePath);if(!cube){cube=new Cubemap(128,TextureFormat.RGBAHalf,true);AssetDatabase.CreateAsset(cube,cubePath);}var cap=new GameObject("Glass2 reflection capture"){hideFlags=HideFlags.HideAndDontSave};var c=cap.AddComponent<Camera>();c.enabled=false;c.transform.position=r.bounds.center+Vector3.up*.15f;c.nearClipPlane=.02f;c.farClipPlane=40;c.clearFlags=CameraClearFlags.SolidColor;c.backgroundColor=new Color(.12f,.13f,.15f);c.allowHDR=true;bool enabled=r.enabled;try{r.enabled=false;if(!c.RenderToCubemap(cube))throw new Exception("Reflection capture failed");}finally{r.enabled=enabled;UnityEngine.Object.DestroyImmediate(cap);}EditorUtility.SetDirty(cube);
 var mp="Assets/BlenderScene3/Materials/Glass2VisibleFrost.mat";var m=AssetDatabase.LoadAssetAtPath<Material>(mp);if(!m){m=new Material(shader);AssetDatabase.CreateAsset(m,mp);}m.shader=shader;m.SetColor("_Color",new Color(.78f,.92f,1,.24f));m.SetFloat("_Frost",4);m.SetFloat("_Smoothness",.80f);m.SetFloat("_Refraction",3);m.SetTexture("_GlassCube",cube);m.renderQueue=3010;EditorUtility.SetDirty(m);Undo.RecordObject(r,"Make glass2 visibly frosted glass");r.sharedMaterials=Enumerable.Repeat(m,r.sharedMaterials.Length).ToArray();PrefabUtility.RecordPrefabInstancePropertyModifications(r);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);File.WriteAllText("D:/-11-scene3-audit/glass2-visible.txt","glass2|shader="+r.sharedMaterial.shader.name+"|frost=4|refractionPixels=3|reflectionF0=0.10|tintStrength=0.24|bounds="+r.bounds+"\nglass1 material unchanged");SceneView.RepaintAll();}catch(Exception e){File.WriteAllText("D:/-11-scene3-audit/glass2-visible-error.txt",e.ToString());}}}
